//! Serialized portable hybrid extension build and actual-consumer host targets.
const std = @import("std");
pub fn steps(b: *std.Build, cuda: *std.Build.Module, glm: *std.Build.Module, mods: anytype, aggregate: *std.Build.Step) void {
    const startup_root=b.createModule(.{.root_source_file=b.path("zig/src/server/startup.zig"),.target=b.graph.host,.optimize=.debug,.link_libc=true});
    const startup_run=b.addRunArtifact(b.addTest(.{.root_module=startup_root,.filters=&.{"V4 startup join:"}}));startup_run.has_side_effects=true;
    b.step("test-v4-startup-join-host","Actual startup join cancellation with process TERM and real Io tasks").dependOn(&startup_run.step);
    const repair_root=b.createModule(.{.root_source_file=b.path("zig/glm_hybrid_repair_host.zig"),.target=b.graph.host,.optimize=.debug,.link_libc=true,.imports=&.{.{.name="glm",.module=glm}}});
    const repair_run=b.addRunArtifact(b.addTest(.{.root_module=repair_root,.filters=&.{"Q1 repair:"}}));repair_run.has_side_effects=true;
    b.step("test-glm-hybrid-repair-host","Q1 source-consuming deadline budget regressions without devices or sockets").dependOn(&repair_run.step);
    const mem_root=b.createModule(.{.root_source_file=b.path("zig/glm_hybrid_memory_host.zig"),.target=b.graph.host,.optimize=.debug,.link_libc=true,.imports=&.{.{.name="glm",.module=glm},.{.name="cuda",.module=cuda},.{.name="core",.module=mods.core},.{.name="engine_api",.module=glm.import_table.get("engine_api").?},.{.name="tp",.module=glm.import_table.get("tp").?}}});
    const cancel_run=b.addRunArtifact(b.addTest(.{.root_module=mem_root,.filters=&.{"V4 startup:"}}));cancel_run.has_side_effects=true;
    b.step("test-v4-attention-cancel-host","Actual GLM/native and family option stop-token boundaries without devices").dependOn(&cancel_run.step);
    const pure_root=b.createModule(.{.root_source_file=b.path("zig/src/families/glm/cuda_hybrid_memory_test.zig"),.target=b.graph.host,.optimize=.debug,.link_libc=true});
    const pure_run=b.addRunArtifact(b.addTest(.{.root_module=pure_root}));pure_run.has_side_effects=true;
    b.step("test-glm-hybrid-memory-pure-host","I3 arithmetic/admission/lifetime module without devices").dependOn(&pure_run.step);
    const mem_test=b.addRunArtifact(b.addTest(.{.root_module=mem_root,.filters=&.{b.option([]const u8,"i3-filter","Private focused I3 consumer selection") orelse "I3 "}}));mem_test.has_side_effects=true;
    const mem_step=b.step("test-glm-hybrid-memory-host","I3 exact native allocation, admission, status and retention consumers");mem_step.dependOn(&mem_test.step);aggregate.dependOn(mem_step);
    const mem_native=b.addRunArtifact(b.addTest(.{.root_module=glm,.filters=&.{"I3 native "}}));mem_native.has_side_effects=true;
    b.step("test-glm-hybrid-memory-native-host","I3 actual native Owned cleanup and retained release").dependOn(&mem_native.step);
    const host_kv = b.createModule(.{ .root_source_file = b.path("zig/glm_kv_host_hybrid_host.zig"), .target = b.graph.host, .optimize = .debug, .link_libc = true, .imports = &.{ .{ .name = "glm", .module = glm }, .{ .name = "cuda", .module = cuda }, .{ .name = "core", .module = mods.core } } });
    const i2_run = b.addRunArtifact(b.addTest(.{ .root_module = host_kv, .filters = &.{b.option([]const u8,"i2-filter","Private focused I2 host consumer selection") orelse "I2 host KV:"} }));
    i2_run.has_side_effects = true;
    const overflow_probe = b.addRunArtifact(b.addExecutable(.{ .name = "i2-overflow-native-check", .root_module = host_kv }));
    overflow_probe.has_side_effects = true;
    overflow_probe.expectExitCode(0);
    overflow_probe.expectStdErrEqual("error: kv host: a call picked more distinct rows than the gather's 8192 slots\nI2_OVERFLOW_NAMED_RESET_OK\n");
    const host_kv_step = b.step("test-glm-kv-host-hybrid-host", "I2 actual host-KV and MTP consuming paths without devices");
    aggregate.dependOn(host_kv_step);
    host_kv_step.dependOn(&i2_run.step);
    host_kv_step.dependOn(&overflow_probe.step);
    const tile524=b.createModule(.{.root_source_file=b.path("zig/glm_524_tile_host.zig"),.target=b.graph.host,.optimize=.debug,.link_libc=true,.imports=&.{.{.name="glm",.module=glm},.{.name="cuda",.module=cuda},.{.name="core",.module=mods.core}}});
    const tile524_run=b.addRunArtifact(b.addTest(.{.root_module=tile524,.filters=&.{"qualification524"}}));tile524_run.has_side_effects=true;
    b.step("test-glm-524-tile-host","Actual bounded temporary attention consumers, no devices").dependOn(&tile524_run.step);
    const gather524_run=b.addRunArtifact(b.addTest(.{.root_module=host_kv,.filters=&.{"I2 host KV: full", "I2 host KV: partial", "I2 host KV: rejected", "I2 host KV: native", "I2 host KV: scalar", "I2 host KV: missing", "I2 host KV: actual", "I2 host KV: same", "I2 host KV: real", "I2 host KV: post-image"}}));gather524_run.has_side_effects=true;
    b.step("test-glm-524-gather-host","Affected valid singleton/gather consumers; stale unrelated peers fixture excluded explicitly").dependOn(&gather524_run.step);
    const owner_run=b.addRunArtifact(b.addTest(.{.root_module=glm,.filters=&.{"hybrid owner:"}}));owner_run.has_side_effects=true;
    b.step("test-glm-hybrid-owner-host","Actual partial and complete attention/expert lifetime consumers with device-boundary fixtures").dependOn(&owner_run.step);
    const bootstrap=b.addRunArtifact(b.addTest(.{.root_module=glm.import_table.get("tp").?,.filters=&.{"hybrid bootstrap:"}}));bootstrap.has_side_effects=true;
    b.step("test-glm-hybrid-bootstrap-host","Actual native internal absolute bootstrap deadlines").dependOn(&bootstrap.step);
    const load=b.addRunArtifact(b.addTest(.{.root_module=glm,.filters=&.{"hybrid load:"}}));load.has_side_effects=true;
    b.step("test-glm-hybrid-load-host","Actual role-selected native checkpoint loader without devices").dependOn(&load.step);
    const root=b.createModule(.{ .root_source_file=b.path("zig/glm_hybrid_host.zig"),.target=b.graph.host,.optimize=.debug,.link_libc=true,.imports=&.{ .{.name="glm",.module=glm},.{.name="cuda",.module=cuda},.{.name="core",.module=mods.core},.{.name="tp",.module=glm.import_table.get("tp").?} } });
    const parent_module=b.createModule(.{.root_source_file=b.path("zig/src/native/cuda_host_close.zig"),.target=b.graph.host,.optimize=.debug,.link_libc=true,.imports=&.{.{.name="cuda",.module=cuda},.{.name="core",.module=mods.core},.{.name="nemotron",.module=mods.nemotron},.{.name="engine_api",.module=glm.import_table.get("engine_api").?}}});
    const parent_test=b.addRunArtifact(b.addTest(.{.root_module=parent_module,.filters=&.{"hybrid parent close:"}}));parent_test.has_side_effects=true;
    b.step("test-glm-hybrid-parent-close-host","Actual native host close preserves all parents on quarantine").dependOn(&parent_test.step);
    const close_module=b.createModule(.{.root_source_file=b.path("zig/src/fabric/tp/roce.zig"),.target=b.graph.host,.optimize=.debug,.link_libc=true,.imports=&.{.{.name="cuda",.module=cuda},.{.name="verbs",.module=glm.import_table.get("tp").?.import_table.get("verbs").?}}});
    const close=b.addRunArtifact(b.addTest(.{.root_module=close_module,.filters=&.{"hybrid close:"}}));close.has_side_effects=true;
    b.step("test-glm-hybrid-close-host","Actual native bounded typed transport close").dependOn(&close.step);
    const engine_test=b.addRunArtifact(b.addTest(.{.root_module=root,.filters=&.{"hybrid engine:"}}));engine_test.has_side_effects=true;
    b.step("test-glm-hybrid-engine-host","Actual native engine role admission before GPU/model reads").dependOn(&engine_test.step);
    const expert_module=b.createModule(.{.root_source_file=b.path("zig/glm_expert.zig"),.target=b.graph.host,.optimize=.debug,.link_libc=true,.imports=&.{.{.name="cuda",.module=cuda},.{.name="glm",.module=glm},.{.name="tp",.module=glm.import_table.get("tp").?}}});
    const expert_memory=b.addRunArtifact(b.addTest(.{.root_module=expert_module,.filters=&.{"I3 expert CLI:"}}));expert_memory.has_side_effects=true;
    b.step("test-glm-hybrid-expert-memory-host","I3 real expert CLI metadata and ownership before driver").dependOn(&expert_memory.step);
    const expert_exe=b.addExecutable(.{.name="tf-glm-expert-cpu-check",.root_module=expert_module});
    const config_files=b.addWriteFiles();
    const config_file=config_files.add("hybrid-expert-check.json", "{\"revision\":3,\"role\":\"expert0\",\"session\":\"00000000000000000000000000000001\",\"model_sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\",\"master\":[\"127.0.0.1\",\"127.0.0.1\"],\"ports\":[29550,29551],\"traffic_class\":104,\"verbs_device\":\"fixture\",\"roce_image\":\"/fixture/unopened.fatbin\",\"setup_ms\":30000,\"transaction_ms\":120000,\"close_ms\":5000,\"served_context\":262144,\"resident_users\":8,\"mtp\":true,\"settings\":{\"pages\":true,\"kv8\":true,\"dense_bits\":4}}" );
    const check=b.addRunArtifact(expert_exe);check.addArg("--config");check.addFileArg(config_file);check.addArgs(&.{"--checkpoint","/fixture/unopened-model","--device","0","--check"});check.expectExitCode(0);check.expectStdErrEqual("CONFIG_ONLY role=expert0 WIRE3 NO_DEVICE\n");check.has_side_effects=true;
    const missing=b.addRunArtifact(expert_exe);missing.addArgs(&.{"--config","/fixture/missing"});missing.expectExitCode(1);missing.has_side_effects=true;
    const entry=b.step("test-glm-hybrid-expert-entry","Execute the actual expert binary parser/config path before any runtime/model/device access");entry.dependOn(&check.step);entry.dependOn(&missing.step);
    const expert_test=b.addRunArtifact(b.addTest(.{.root_module=expert_module,.filters=&.{"hybrid CLI:"}}));expert_test.has_side_effects=true;
    b.step("test-glm-hybrid-cli-host","Actual expert command argument parser without runtime initialization").dependOn(&expert_test.step);
    const peer_module=b.createModule(.{.root_source_file=b.path("zig/src/families/glm/cuda_hybrid_provider_test.zig"),.target=b.graph.host,.optimize=.debug,.link_libc=true,.imports=&.{.{.name="cuda",.module=cuda},.{.name="glm",.module=glm},.{.name="tp",.module=glm.import_table.get("tp").?}}});
    const peer_run=b.addRunArtifact(b.addTest(.{.root_module=peer_module,.filters=&.{"hybrid peer:"}}));peer_run.has_side_effects=true;
    b.step("test-glm-hybrid-peer-host","Composed request/reply peer directions with bounded duplex framing").dependOn(&peer_run.step);
    const io_module=b.createModule(.{.root_source_file=b.path("zig/src/families/glm/cuda_hybrid_transport_test.zig"),.target=b.graph.host,.optimize=.debug,.link_libc=true,.imports=&.{.{.name="cuda",.module=cuda},.{.name="glm",.module=glm},.{.name="tp",.module=glm.import_table.get("tp").?}}});
    const io_run=b.addRunArtifact(b.addTest(.{.root_module=io_module,.filters=&.{"hybrid native IO:"}}));io_run.has_side_effects=true;
    b.step("test-glm-hybrid-native-host","Actual native frame CUDA-copy and event completion boundary").dependOn(&io_run.step);
    const transport=b.addRunArtifact(b.addTest(.{.root_module=root,.filters=&.{"hybrid transport:"}}));transport.has_side_effects=true;
    b.step("test-glm-hybrid-transport-host","Actual native-pair framing/identity consumer without devices").dependOn(&transport.step);
    const run=b.addRunArtifact(b.addTest(.{.root_module=root,.filters=&.{"hybrid provider:"}}));
    run.has_side_effects=true;
    b.step("test-glm-hybrid-provider-host","Actual native hybrid provider/fill consumers without devices").dependOn(&run.step);
}
